// HQ Board proxy — cache reads, always pass writes straight through.
//
// WHY: every device polls independently, and each poll is its own Apps Script
// execution. A consumer account has ~90 minutes of script runtime PER DAY, so
// at ~4s a tick one board burns ~12 min/hour — ten boards would exhaust the
// day's quota in under an hour, taking n8n inserts and Telegram down with it.
// Caching here makes the Apps Script cost INDEPENDENT of how many devices are
// watching: one board or fifty, the same handful of calls per minute.
//
// ⚠ READS ONLY. boardStatus is a WRITE (the ✓ Pick button) and must NEVER be
// served from, or stored in, the cache.

const sd     = $getWorkflowStaticData('global');
const body   = ($input.first().json.body) || {};
const action = String(body.action || '');

const EXEC_URL  = '__APPS_SCRIPT_EXEC_URL__';
const TOKEN     = '__APP_SECRET_TOKEN__';
const CACHE_MS  = 15000;          // a board polls at 20s; 15s of staleness is invisible
const CACHEABLE = ['boardTick'];  // NOT boardStatus. Not ever.

const now      = Date.now();
const cacheable = CACHEABLE.includes(action);

// --- serve from cache -------------------------------------------------------
if (cacheable && sd.tick && sd.tickAt && (now - sd.tickAt) < CACHE_MS) {
  const hit = JSON.parse(sd.tick);
  hit._cached = true;
  hit._ageMs  = now - sd.tickAt;
  return [{ json: hit }];
}

// --- otherwise ask Apps Script ---------------------------------------------
let res;
try {
  res = await this.helpers.httpRequest({
    method:  'POST',
    url:     EXEC_URL,
    body:    Object.assign({}, body, { token: TOKEN }),
    json:    true,
    timeout: 45000
  });
} catch (err) {
  // Never throw: a thrown Code node returns no body, and the board would see a
  // dead socket instead of something it can report. Hand back a readable error.
  return [{ json: { error: 'proxy: ' + (err.message || String(err)) } }];
}

// --- store, but ONLY a response that actually looks like a tick -------------
// Caching an error would pin the board to it for the whole cache window.
if (cacheable && res && res.cockpit) {
  sd.tick   = JSON.stringify(res);
  sd.tickAt = now;
}

return [{ json: res }];
